## 解题方法

### 方法一：动态规划

```js
/**
 * @param {number} n
 * @return {number}
 */
var climbStairs = function (n) {
  if (n === 1) {
    return 1;
  }
  const dp = [1, 1];
  for (let i = 2; i `<=` n; i += 1) {
    dp[i] = dp[i - 2] + dp[i - 1];
  }
  return dp[n];
};
```

### 方法二：动态规划 + 双指针

![climbing-stairs](https://fxpby.oss-cn-beijing.aliyuncs.com/blogImg/leetcode/climbing-stairs/climbing-stairs.png)

```js
/**
 * @param {number} n
 * @return {number}
 */
var climbStairs = function (n) {
  if (n === 1) {
    return 1;
  }
  let dp1 = 1;
  let dp2 = 1;
  for (let i = 2; i `<=` n; i += 1) {
    const temp = dp1;
    dp1 = dp2;
    dp2 = dp2 + temp;
  }
  return dp2;
};
```

