输出：[0]
```

## 解题方法

### 方法一：递归

- 步骤
  - 从链表头部开始比较大小，小的就是合并后新链表的最小值,再用较小的 `next.val` 和较大的 `val` 比较递归
  - 若两个链表有一个为空，结束递归
- 复杂度分析
  - 时间复杂度：O(n + m),n，m 分别为两个链表长度，每次递归都会去掉 list1 或 list2 的头节点直至至少一个链表为空
  - 空间复杂度：O(n + m),n，m 分别为两个链表长度,递归调用栈空间取决于递归的深度

```js
/**
 * Definition for singly-linked list.
 * function ListNode(val, next) {
 *     this.val = (val===undefined ? 0 : val)
 *     this.next = (next===undefined ? null : next)
 * }
 */
/**
 * @param {ListNode} list1
 * @param {ListNode} list2
 * @return {ListNode}
 */
var mergeTwoLists = function (list1, list2) {
  if (list1 === null) {
    return list2;
  }
  if (list2 === null) {
    return list1;
  }
  if (list1.val `<=` list2.val) {
    list1.next = mergeTwoLists(list1.next, list2);
    return list1;
  } else {
    list2.next = mergeTwoLists(list2.next, list1);
    return list2;
  }
};
```

### 方法二：迭代

- 步骤
  - 创建一个新链表
  - 比较两个链表头，把小的存入新链表，向后移动一步
  - 若有一个链表遍历结束了，直接把剩余部分追加到新链表即可（有序）
- 复杂度分析
  - 时间复杂度：O(n + m)
  - 空间复杂度：O(1)

```js
/**
 * Definition for singly-linked list.
 * function ListNode(val, next) {
 *     this.val = (val===undefined ? 0 : val)
 *     this.next = (next===undefined ? null : next)
 * }
 */
/**
 * @param {ListNode} list1
 * @param {ListNode} list2
 * @return {ListNode}
 */
var mergeTwoLists = function (list1, list2) {
  const newList = new ListNode(0);
  let cur = newList;
  while (list1 && list2) {
    if (list1.val `<=` list2.val) {
      cur.next = list1;
      list1 = list1.next;
    } else {
      cur.next = list2;
      list2 = list2.next;
    }
    cur = cur.next;
  }
  cur.next = list1 ? list1 : list2;
  return newList.next;
};
```

## 题目描述

给你一个链表的头节点 head 和一个整数 val ，请你删除链表中所有满足 Node.val == val 的节点，并返回 新的头节点 。

示例 1：

```js
输入：head = [1,2,6,3,4,5,6], val = 6
输出：[1,2,3,4,5]
```

示例 2：

```js
输入：head = [], val = 1
输出：[]
```

示例 3：

```js
输入：head = [7,7,7,7], val = 7
输出：[]
```

提示：

- 列表中的节点数目在范围 [0, 104] 内
- 1 `<=` Node.val `<=` 50
- 0 `<=` val `<=` 50

## 解题方法

### 方法一：迭代+虚拟头结点

- 思路：初始化虚拟头结点和指向 head 的指针 temp，指针后移，判断下一节点值是否为 val
  - 若相等，则指针指向下下个节点，即删除了下一个节点
  - 若不等，则继续后移
- 复杂度分析：
  - 时间复杂度：O(n)，n 为链表长度，需遍历链表一次
  - 空间复杂度：O(1)

```js
/**
 * Definition for singly-linked list.
 * function ListNode(val, next) {
 *     this.val = (val===undefined ? 0 : val)
 *     this.next = (next===undefined ? null : next)
 * }
 */
/**
 * @param {ListNode} head
 * @param {number} val
 * @return {ListNode}
 */
var removeElements = function (head, val) {
  let dummyHead = new ListNode(0);
  dummyHead.next = head;
  let temp = dummyHead;

  while (temp.next !== null) {
    if (temp.next.val === val) {
      temp.next = temp.next.next;
    } else {
      temp = temp.next;
    }
  }

  return dummyHead.next;
};
```

### 方法二：递归

- 思路：对每个子节点调用 removeElements，如果是 null 就返回 null，如果是给定值就返回当前节点的下一个节点，不是则返回当前节点
- 复杂度分析：
  - 时间复杂度：O(n),链表长度，需遍历链表一次
  - 空间复杂度：O(n),链表长度，取决于递归调用栈，最多为 n

```js
/**
 * Definition for singly-linked list.
 * function ListNode(val, next) {
 *     this.val = (val===undefined ? 0 : val)
 *     this.next = (next===undefined ? null : next)
 * }
 */
/**
 * @param {ListNode} head
 * @param {number} val
 * @return {ListNode}
 */
var removeElements = function (head, val) {
  if (head === null) {
    return head;
  }
  head.next = removeElements(head.next, val);
  if (head.val === val) {
    return head.next;
  } else {
    return head;
  }
};
```

## 题目描述

存在一个按升序排列的链表，给你这个链表的头节点 head ，请你删除所有重复的元素，使每个元素 只出现一次 。

返回同样按升序排列的结果链表。

```js
输入：head = [1,1,2]
输出：[1,2]

输入：head = [1,1,2,3,3]
输出：[1,2,3]
```

## 解题方法

### 方法一：单指针+迭代

- 思路：
  - 因为是已经排序过的，所以重复元素都是相邻的，迭代指针，比较节点和next节点值是否相同即可
- 步骤：
  - 创建指针指向头节点，迭代指针
  - 若指针当前值和next指针值相同，把当前next指向next.next
- 复杂度分析：
  - 时间复杂度：O(N), N 为链表长度
  - 空间复杂度：O(1)，存储单个值

```js
/**
 * Definition for singly-linked list.
 * function ListNode(val, next) {
 *     this.val = (val===undefined ? 0 : val)
 *     this.next = (next===undefined ? null : next)
 * }
 */
/**
 * @param {ListNode} head
 * @return {ListNode}
 */
var deleteDuplicates = function (head) {
  let p = head;

  while (p && p.next) {
    if (p.val === p.next.val) {
      p.next = p.next.next;
    } else {
      p = p.next;
    }
  }

  return head;
};
```

### 方法二：双指针+迭代

- 思路：
  - 创建 prev 和 cur 两个节点，分别指向 head 和 head.next
  - 判断 prev 和 cur 值是否相等
    - 相等则 prev.next = cur.next，即删除 cur 节点,cur 继续后移
    - 不等则后移 prev，cur 也继续后移
  - 直至 cur 到最后，返回 head
- 复杂度分析：
  - 时间复杂度：O(n)
  - 空间复杂度：O(1)

```js
/**
 * Definition for singly-linked list.
 * function ListNode(val, next) {
 *     this.val = (val===undefined ? 0 : val)
 *     this.next = (next===undefined ? null : next)
 * }
 */
/**
 * @param {ListNode} head
 * @return {ListNode}
 */
var deleteDuplicates = function (head) {
  if (head === null || head.next === null) {
    return head;
  }

  let prev = head;
  let cur = head.next;

  while (prev && cur) {
    if (prev.val === cur.val) {
      prev.next = cur.next;
    } else {
      prev = prev.next;
    }
    cur = cur.next;
  }

  return head;
};
```

### 方法三：虚拟头节点+迭代

- 思路：创建虚拟头节点指向 head，cur 节点指向头部 head.next
  - cur or cur.next 为 null 时，说明链表没有去重的必要了
  - 如果 cur.val 和 cur.next.val 相等则去重
  - 如果不等移动 cur 指针
- 复杂度分析：
  - 时间复杂度：O(n),n 为链表长度
  - 空间复杂度：O(1)

```js
/**
 * Definition for singly-linked list.
 * function ListNode(val, next) {
 *     this.val = (val===undefined ? 0 : val)
 *     this.next = (next===undefined ? null : next)
 * }
 */
/**
 * @param {ListNode} head
 * @return {ListNode}
 */
var deleteDuplicates = function (head) {
  if (head === null) {
    return head;
  }

  let dummyHead = new ListNode(0, head);
  let cur = dummyHead.next;

  while (cur && cur.next) {
    if (cur.val === cur.next.val) {
      cur.next = cur.next.next;
    } else {
      cur = cur.next;
    }
  }

  return dummyHead.next;
};
```

### 方法四：递归

- 思路：递归执行到链表最后，从后向前处理；遇到相同节点，就删除 head.next节点，返回 head
- 复杂度分析：
  - 时间复杂度：O(n)
  - 空间复杂度：O(n)

```js
/**
 * Definition for singly-linked list.
 * function ListNode(val, next) {
 *     this.val = (val===undefined ? 0 : val)
 *     this.next = (next===undefined ? null : next)
 * }
 */
/**
 * @param {ListNode} head
 * @return {ListNode}
 */
var deleteDuplicates = function (head) {
  if (head === null) {
    return head;
  }
  if (head.next !== null) {
    head.next = deleteDuplicates(head.next);
    if (head.val === head.next.val) {
      head.next = head.next.next;
    }
  }
  return head;
};
```

### 方法五：快慢指针

- 思路：
  - 快慢指针都指在头部，
  - 快指针一直往前走，如果两个指针值不相等，慢指针的next指向快指针`slow.next = fast`,去除重复元素；`slow = fast`同步慢指针位置
  - 慢指针就是最终结果尾部，去除后续链接，断掉慢指针后面所有重复元素，返回 head

```js
/**
 * Definition for singly-linked list.
 * function ListNode(val, next) {
 *     this.val = (val===undefined ? 0 : val)
 *     this.next = (next===undefined ? null : next)
 * }
 */
/**
 * @param {ListNode} head
 * @return {ListNode}
 */
var deleteDuplicates = function (head) {
  if (head === null || head.next === null) {
    return head;
  }

  let slow = head;
  let fast = head;

  while (fast) {
    if (slow.val !== fast.val) {
      slow.next = fast;
      slow = slow.next;
    }
    fast = fast.next;
  }
  // 断尾，删除多余重复元素
  slow.next = null;
  return head;
};
```

## 题目描述

给你单链表的头指针 head 和两个整数 left 和 right ，其中 left `<=` right 。请你反转从位置 left 到位置 right 的链表节点，返回 反转后的链表 。

示例 1：

```js
输入：head = [1,2,3,4,5], left = 2, right = 4
输出：[1,4,3,2,5]
```

示例 2：

```js
输入：head = [5], left = 1, right = 1
输出：[5]
```

提示：

- 链表中节点数目为 n
- 1 `<=` n `<=` 500
- -500 `<=` Node.val `<=` 500
- 1 `<=` left `<=` right `<=` n

## 解题方法

### 方法一：迭代

- 思路：切断 [left 到 right] 的子链，反转后再连接
- 复杂度分析：
  - 时间复杂度：O(n)
  - 空间复杂度：O(1)

```js
// 复习一下 206 题的 反转单链表
const reverseList = (head) => {
  let pre = null;
  let cur = head;

  while (cur !== null) {
    const temp = cur.next;
    cur.next = pre;
    pre = cur;
    cur = temp;
  }
  return pre;
};

var reverseBetween = function (head, left, right) {
  // 创建虚拟头节点
  const dummyNode = new ListNode(0, head);
  dummyNode.next = head;

  let pre = dummyNode;

  // 获取 left 的前一个节点
  for (let i = 0; i < left - 1; i += 1) {
    pre = pre.next;
  }

  // 获取左节点
  let leftNode = pre.next;

  // 获取右节点
  let rightNode = pre;
  for (let i = 0; i < right - left + 1; i += 1) {
    rightNode = rightNode.next;
  }

  // 获取右节点的后一个节点
  let curr = rightNode.next;

  // 切断子链
  pre.next = null;
  rightNode.next = null;

  // 反转子链
  reverseList(leftNode);

  // 拼接
  pre.next = rightNode;
  leftNode.next = curr;

  return dummyNode.next;
};
```

## 题目描述

给定一个只包括 '('，')'，'{'，'}'，'['，']' 的字符串 s ，判断字符串是否有效。

有效字符串需满足：

- 左括号必须用相同类型的右括号闭合。
- 左括号必须以正确的顺序闭合。

Given a string s containing just the characters '(', ')', '{', '}', '[' and ']', determine if the input string is valid.

An input string is valid if:

- Open brackets must be closed by the same type of brackets.
- Open brackets must be closed in the correct order.

## 解题方法

### 方法一: 栈

- 思路：
  - 遇到左括号时，后续遍历需要一个相同类型的右括号才可以使其闭合。

  - **靠后遇到的左括号需要优先闭合**，所以把左括号推入栈顶，遇到右括号需要个相同类型的左括号闭合，
继而去判断左括号类型，如何类型不匹配或者栈里没有左括号，那就直接判定不合法。

  - 遍历结束后如果栈里没有元素（左括号），说明之前推进去的左括号都闭合了👏，如果有元素，那就判定不合法

- 步骤：
  - 创建一个栈
  - 扫描字符串
    - 遇到左括号 入栈
    - 遇到和栈顶括号匹配的右括号 出栈
    - 遇到和栈顶括号类型不匹配的 判定不合法
  - 最后栈空了就合法，否则不合法

- 复杂度分析：
  - 时间复杂度：O(N), s.length
  - 空间复杂度：O(N), 栈中字符数量为n, 即s为`(([{(((`(n个单边符号)

```js
var isValid = function(s) {
  if (s.length % 2) {
    return false
  }

  const stack = []
  const pairObj = {
    ')': '(',
    '}': '{',
    ']': '['
  }

  for(let ch of s) {
    if ([')', '}', ']'].includes(ch)) {
      if (!stack.length || stack[stack.length - 1] !== pairObj[ch]) {
        return false
      }
      stack.pop()
    } else {
      stack.push(ch)
    }
  }

  return !stack.length
};
```

### 方法二：replace大法

- 思路：有类型一样的括号咱就替了他🎯，替到什么都不剩就是合法的👏

```js
var isValid = function(s) {
  let len = s.length
  while (len && len % 2 === 0) {
    s = s.replace('()', '').replace('{}', '').replace('[]', '')
    if (s.length === len) {
      return false
    }
    len = s.length
  } 
  return len === 0
};
```

## 题目描述

给定字符串 s 和 t ，判断 s 是否为 t 的子序列。

字符串的一个子序列是原始字符串删除一些（也可以不删除）字符而不改变剩余字符相对位置形成的新字符串。（例如，"ace"是"abcde"的一个子序列，而"aec"不是）。

## 解题方法

## 方法一：双指针

```js
var isSubsequence = function (s, t) {
  if (s.length > t.length) {
    return false
  }

  if (s.length === 0) {
    return true
  }

  for (let i = 0, j = 0; j < t.length; j += 1) {
    if (s[i] === t[j]) {
      i += 1
      if (i === s.length) {
        return true
      }
    }
  }

  return false
};
```

