  switch (val.type) {
    case 'olu':
      break
    case 'study':
      break
    default:
      // 'check' is declared but its value is never read.ts(6133)
      // Type 'C' is not assignable to type 'never'.ts(2322)
      const check:never = val
      break
  }
}
```

